import { TextEncoder } from "https://deno.land/std@0.200.0/node/text_encode.ts";

/**
 * Compare two strings in constant time for security (timing attack prevention).
 * Uses UTF-8 byte comparison, not UTF-16 code unit comparison.
 */
export function timingSafeEqual(a: string, b: string): boolean {
  const encoder = new TextEncoder();
  const aBytes = encoder.encode(a);
  const bBytes = encoder.encode(b);

  // Use constant-time comparison
  const minLength = Math.min(aBytes.length, bBytes.length);
  let result = 0;

  for (let i = 0; i < minLength; i++) {
    result |= aBytes[i] ^ bBytes[i];
  }

  result |= aBytes.length ^ bBytes.length;

  return result === 0;
}

